head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gIsurCd;
scwin.gImprRegDd; //개선계획서 등록일자
scwin.gImprRegDd2; //이행보고서 등록일자
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gLstCnt = 0;
scwin.vScrenID = 'ULDSTF35109.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetProvider = function() {
    var url = frame.srcUrl;
    var arr = url.split("?");
    //alert("arr=>"+ arr[1]);
    return (arr.length >= 1 ? arr[1] : undefined);
};
scwin.fn_GetParentValue = function() {
    var pvd = scwin.fn_GetProvider();
    gPvd = pvd;
    //alert("pvd="+ pvd);
    if (pvd != null) {
        scwin.gIsurCd = pvd.split("=")[1];
        if ($c.ut.trim(scwin.gIsurCd).length == 5) {
            //alert(gIsurCd);
            $c.stf.setObjectValue(txb_isur_cd, scwin.gIsurCd);
            fn_Search();
        }
    }
};
scwin.fn_SetCode = function() {
    // 벌점부과유형  셋팅
    dts_ImpostRsn.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=PNLT_IMPOST_RSN_CD";
    dts_ImpostRsn.Reset();

    // 벌점부과사유  셋팅
    dts_ImpostGraceRsn.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=DESIGN_GRACE_RSN_CD";
    dts_ImpostGraceRsn.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !벌점--;
클릭-- > function() {
    // 법인코드 자리수 체크 
    if ($c.stf.getObjectValue(txb_isur_cd).length != 5) {
        $c.win.alert("회사코드 5자리를 올바르게 입력하십시오.");
        txb_isur_cd.focus();
        return;
    }
    scwin.fn_Clear();

    // 1. 벌점부과현황 조회
    var url = "/PenaltyImposition.do?method=readPenaltyStatInfo4K&inputMessageId=PNLTINFO_INOUT" + "&outputMessageId=PNLTINFO_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LD_MKT_TP=2" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //  데이타 조회
    dts_pnltsat_info.DataID = encodeURI(url);
    dts_pnltsat_info.reset();

    // 2. 벌점부과 상세내역
    //txb_TotalCnt.value = "총건수 : " ;	
    var url_list = "/PenaltyImposition.do?method=listPenaltyHistory4K&inputMessageId=PNLTINFO_INOUT" + "&outputMessageId=PNLTDTLLIST_OUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&LD_MKT_TP=2";


    //  데이타 조회
    dts_pnlt_history.DataID = encodeURI(url_list);
    dts_pnlt_history.reset();

    // 3. 개선계획서 조회
    var url_file = "/PenaltyImposition.do?method=readPerfmDtlFileInfo&inputMessageId=DUTY_PERFM_DTL_INOUT" + "&outputMessageId=DUTY_PERFM_DTL_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);

    //  데이타 조회
    dts_imprschdl_file.DataID = encodeURI(url_file);
    dts_imprschdl_file.reset();

    // 주의조치 내역  셋팅
    dts_CautnActDtl.DataID = "/PenaltyImposition.do?method=getCautnActRsn&inputMessageId=CAUTN_ACT_DTL_INOUT" + "&outputMessageId=CAUTN_ACT_DTL_INOUT" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd);
    dts_CautnActDtl.Reset();
};






/*
	// 그리드에서 클릭 row의 변수셋팅
	function fn_setContnId(obj) {
		gIsurCd = dts_pnlt_list.NameString(eval(obj),"ISUR_CD");
		//alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);
	}
*/

scwin.fn_CheckValue = function() {
    if ($c.stf.getObjectValue(txb_isur_cd) != $c.stf.getObjectValue(txb_isurcd)) {
        $c.win.alert("회사 선택후 벌점부과현황을 조회후에 입력처리가 가능합니다.");
        txb_isur_cd.focus();
        return false;
    }
    if (edt_impost_dd.getValue() == "" && edt_design_grace_fix_dd.getValue() == "") {
        $c.win.alert("벌점부과일or지정유예 결정일은 필수입니다.");
        return false;
    }

    //벌점 부과 경우
    if ($c.stf.getObjectValue(edt_impost_dd) != "") {
        if ($c.stf.getObjectValue(txb_pnlt) == "") {
            $c.win.alert("벌점을 입력하십시오");
            txb_pnlt.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_pnlt) != '' && scwin.isNumJum($c.stf.getObjectValue(txb_pnlt)) == false) {
            $c.win.alert("벌점은 숫자만 입력가능합니다.");
            txb_pnlt.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_sanctn_amt) == "") {
            $c.win.alert("0 이상의 금액을 입력하셔야 합니다.");
            txb_sanctn_amt.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_sanctn_amt) != '' && $c.ut.isNum($c.stf.getObjectValue(txb_sanctn_amt)) == false) {
            $c.win.alert("숫자만 입력가능합니다.");
            txb_sanctn_amt.focus();
            return false;
        }
    }

    //지정유예의 경우
    if ($c.stf.getObjectValue(edt_design_grace_fix_dd) != "") {
        if ($c.stf.getObjectValue(txb_DESIGN_GRACE_PNLT) == "") {
            $c.win.alert("지정유예 벌점을 입력하십시오");
            txb_DESIGN_GRACE_PNLT.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_designGraceRsnCd) == "") {
            $c.win.alert("지정유예 사유를 입력하십시오");
            cmb_designGraceRsnCd.focus();
            return false;
        }
        if ($c.stf.getObjectValue(edt_gracepd_end_dd) == "") {
            $c.win.alert("유예기간 만료일은 필수입니다.");
            edt_gracepd_end_dd.focus();
            return false;
        }
        if ($c.stf.getObjectValue(txb_DESIGN_GRACE_PNLT) != '' && scwin.isNumJum($c.stf.getObjectValue(txb_DESIGN_GRACE_PNLT)) == false) {
            $c.win.alert("지정유예 벌점은 숫자만 입력가능합니다.");
            txb_DESIGN_GRACE_PNLT.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(edt_impost_dd) != "" || $c.stf.getObjectValue(edt_design_grace_fix_dd) != "") {
        if ($c.stf.getObjectValue(edt_rsnoccr_dd) == "") {
            $c.win.alert("사유발생일을 입력하십시오");
            edt_rsnoccr_dd.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_ImpostRsn) == "") {
            $c.win.alert("벌점(제재금)부과사유를 선택하십시오");
            cmb_ImpostRsn.focus();
            return false;
        }
    }
    return true;
};
scwin.isNumJum = function(sVal) {
    if (('0' < sVal) || ('9' > sVal) || ('.' == sVal)) {
        return true;
    } else {
        return false;
    }
};



// 벌점 입력
scwin.fn_Insert = function() {
    if (scwin.fn_CheckValue() == false) {
        return;
    }
    dts_Pnlt_Input.insertRow();
    dts_Pnlt_Input.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_isurcd));
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_DD", $c.stf.getObjectValue(edt_impost_dd));
    dts_Pnlt_Input.setCellData(1, "RSN_OCCR_DD", $c.stf.getObjectValue(edt_rsnoccr_dd));
    //		dts_Pnlt_Input.NameValue(1,"PNLT_IMPOST_TP_CD") = getObjectValue(cmb_ImpostTp) ;
    dts_Pnlt_Input.setCellData(1, "PNLT_IMPOST_RSN_CD", $c.stf.getObjectValue(cmb_ImpostRsn));
    dts_Pnlt_Input.setCellData(1, "VIOL_SANCTN_AMT", $c.stf.getObjectValue(txb_sanctn_amt));
    dts_Pnlt_Input.setCellData(1, "PNLT", $c.stf.getObjectValue(txb_pnlt));
    dts_Pnlt_Input.setCellData(1, "LD_MKT_TP", js_market);
    dts_Pnlt_Input.setCellData(1, "CONFRMR_EMP_NO", js_emp_no);
    dts_Pnlt_Input.setCellData(1, "REMK", $c.stf.getObjectValue(txa_remk));
    dts_Pnlt_Input.setCellData(1, "DESIGN_GRACE_FIX_DD", $c.stf.getObjectValue(edt_design_grace_fix_dd));
    dts_Pnlt_Input.setCellData(1, "GRACEPD_END_DD", $c.stf.getObjectValue(edt_gracepd_end_dd));
    dts_Pnlt_Input.setCellData(1, "DESIGN_GRACE_RSN_CD", $c.stf.getObjectValue(cmb_designGraceRsnCd));
    dts_Pnlt_Input.setCellData(1, "DESIGN_GRACE_PNLT", $c.stf.getObjectValue(txb_DESIGN_GRACE_PNLT));
    var actTp = 0;
    var alertMsg = "벌점입력";
    if ($c.stf.getObjectValue(edt_impost_dd) == "") {
        actTp = 1;
        alertMsg = "지정유예";
    }
    var vAnswer = confirm(alertMsg + ' 처리를 하시겠습니까?');
    if (vAnswer == true) {
        trs_Pnlt_Input.Action = "/PenaltyImposition.do?method=registerKosdaqPenalty&inputMessageId=PNLTDATA_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        trs_Pnlt_Input.KeyValue = "JSP(I:pInput=dts_Pnlt_Input)";
        trs_Pnlt_Input.Post();
    }
};
scwin.fn_delete = function(row) {
    var com_nm = dts_pnltsat_info.getCellData(1, "CO_NM");
    var occr_dd = dts_pnlt_history.getCellData(row, "RSN_OCCR_DD");
    var vAnswer = confirm(com_nm + '(사유발생일:' + occr_dd + ') 항목을 삭제처리 하시겠습니까?');
    if (vAnswer == true) {
        // 가우스헤더 셋팅
        dts_Pnlt_Input.insertRow();
        dts_Pnlt_Input.setCellData(1, "CONFRMR_EMP_NO", js_emp_no);
        dts_Pnlt_Input.setCellData(1, "ISUR_CD", dts_pnlt_history.getCellData(row, "ISUR_CD"));
        dts_Pnlt_Input.setCellData(1, "PNLT_SEQ", dts_pnlt_history.getCellData(row, "PNLT_SEQ"));
        dts_Pnlt_Input.setCellData(1, "RSN_OCCR_DD", dts_pnlt_history.getCellData(row, "RSN_OCCR_DD"));
        dts_Pnlt_Input.setCellData(1, "LD_MKT_TP", js_market);
        dts_Pnlt_Input.setCellData(1, "GRACEPD_END_DD", dts_pnlt_history.getCellData(row, "GRACEPD_END_DD")); //일정에서 삭제하기 위해 필요.
        trs_Pnlt_Input.Action = "/PenaltyImposition.do?method=deleteKosdaqPenalty&inputMessageId=PNLTDATA_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        trs_Pnlt_Input.KeyValue = "JSP(I:pInput=dts_Pnlt_Input)";
        trs_Pnlt_Input.Post();
    }
};




// 입력항목 clear
scwin.fn_Clear = function() {
    $c.stf.setObjectValue(edt_impost_dd, "");
    $c.stf.setObjectValue(edt_rsnoccr_dd, "");
    $c.stf.setObjectValue(cmb_ImpostRsn, "");
    $c.stf.setObjectValue(txb_sanctn_amt, "");
    $c.stf.setObjectValue(txb_pnlt, "");
    $c.stf.setObjectValue(txa_remk, "");
};




//지정유예사유를 수정한 경우 지정유예 결정일이 있어야함.
scwin.check_design_grace_fix_dd = function(obj) {
    if ($c.stf.getObjectValue(obj) != '') {
        if (edt_design_grace_fix_dd.getValue() == '') {
            $c.stf.setObjectValue(obj, '');
            $c.win.alert('지정유예결정일을 먼저 입력하셔야 합니다.');
        }
    }
};




//gubunPNLT  1:벌점(제재금)부과일, 2:지정유예걸정일이 입력된 경우.
scwin.checkGraceInfo = function(gubunPNLT) {
    if (gubunPNLT == '1') {
        if (edt_impost_dd.getValue() != '') {
            edt_design_grace_fix_dd.setValue('');
            txb_DESIGN_GRACE_PNLT.setDisabled(true);
            txb_DESIGN_GRACE_PNLT.setValue('');
            cmb_designGraceRsnCd.setDisabled(true);
            cmb_designGraceRsnCd.setSelectedIndex(0);
            edt_gracepd_end_dd.setDisabled(true);
            edt_gracepd_end_dd.setValue('');
            txb_pnlt.setDisabled(false);
            txb_sanctn_amt.setDisabled(false);
        }
    } else {
        if (edt_design_grace_fix_dd.getValue() != '') {
            edt_impost_dd.setValue('');
            txb_pnlt.setDisabled(true);
            txb_pnlt.setValue('');
            txb_sanctn_amt.setValue('');
            txb_sanctn_amt.setDisabled(true);
            txb_DESIGN_GRACE_PNLT.setDisabled(false);
            cmb_designGraceRsnCd.setDisabled(false);
            edt_gracepd_end_dd.setDisabled(false);
            scwin.getWorkdayIn6Months();
        }
    }
};
scwin.getWorkdayIn6Months = function() {
    dts_workday_in_6_months.DataID = "/PenaltyImposition.do?method=getWorkdayIn6months&inputMessageId=PNLTDTLLIST_OUT" + "&outputMessageId=PNLTDTLLIST_OUT" + "&DESIGN_GRACE_FIX_DD=" + edt_design_grace_fix_dd.getValue() + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_workday_in_6_months.reset();
};


// 1개선계획서파일 or  2주의조치내역 다운로드
scwin.fn_filedown = function(ver) {
    var tIsur_cd = '';
    var tSeq = '';
    var tGubun = '';
    //var vRegDd = dts_imprschdl_file.NameString(1,"IMPR_REG_DD");	
    if (ver == "1") {
        tIsur_cd = dts_imprschdl_file.getCellData(1, "ISUR_CD");
        tSeq = dts_imprschdl_file.getCellData(1, "SEQ");
        tGubun = "60";
    } else {
        tIsur_cd = dts_CautnActDtl.getCellData(1, "ISUR_CD");
        tSeq = dts_CautnActDtl.getCellData(1, "SEQ");
        tGubun = "61";
    }
    var link = "/filedownload.do?" + "ISUR_CD=" + tIsur_cd + "&SEQ=" + tSeq + "&gubun=" + tGubun + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
    location.href = encodeURI(link);
};
scwin.deleteCautnActDtl = function() {
    var vAnswer = confirm('주의조치 내역을 삭제처리 하시겠습니까?');
    if (vAnswer == true) {
        dts_CautnActDtl_input.insertRow();
        dts_CautnActDtl_input.setCellData(1, "ISUR_CD", dts_CautnActDtl.getCellData(1, "ISUR_CD"));
        dts_CautnActDtl_input.setCellData(1, "SEQ", dts_CautnActDtl.getCellData(1, "SEQ"));
        dts_CautnActDtl_input.setCellData(1, "EMP_NO", js_emp_no);
        trs_Pnlt_Input.Action = "/PenaltyImposition.do?method=deleteCautnActRsn&inputMessageId=CAUTN_ACT_DTL_INOUT&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Pnlt_Input.KeyName = "toinb_dataid4";
        trs_Pnlt_Input.KeyValue = "JSP(I:pInput=dts_CautnActDtl_input)";
        trs_Pnlt_Input.Post();
    }
};
scwin.dts_ImpostRsn_OnLoadCompleted = function(rowcount) {
    dts_ImpostRsn.UseFilter = true;
    dts_ImpostRsn.Filter();
    dts_ImpostRsn.sort("VALUE", 0);
    //dts_ImpostRsn.sort(); // W-Craft 주석처리 

};
scwin.dts_ImpostRsn_OnFilter = function(row) {
    // 코스닥용 벌점부과사유 보여주기
    if (dts_ImpostRsn.getCellData(row, "value") == '1' ||
        dts_ImpostRsn.getCellData(row, "value") == '2' ||
        dts_ImpostRsn.getCellData(row, "value") == '3' ||
        dts_ImpostRsn.getCellData(row, "value") == '4' ||
        dts_ImpostRsn.getCellData(row, "value") == '6' ||
        dts_ImpostRsn.getCellData(row, "value") == '7' ||
        dts_ImpostRsn.getCellData(row, "value") == '8' ||
        dts_ImpostRsn.getCellData(row, "value") == '9' ||
        dts_ImpostRsn.getCellData(row, "value") == 'B' ||
        dts_ImpostRsn.getCellData(row, "value") == 'C' ||
        dts_ImpostRsn.getCellData(row, "value") == '') {
        if (dts_ImpostRsn.getCellData(row, "value") == '4') {
            dts_ImpostRsn.setCellData(row, "text", '개선(이행)보고서미제출');
        }
        return true;
    } else {
        return false;
    }
};
scwin.dts_ImpostGraceRsn_OnLoadCompleted = function(rowcount) {
    dts_ImpostGraceRsn.UseFilter = true;
    dts_ImpostGraceRsn.Filter();
    dts_ImpostGraceRsn.sort("VALUE", 0);
    //dts_ImpostGraceRsn.sort(); // W-Craft 주석처리 

};
scwin.dts_pnltsat_info_OnLoadError = function() {
    $c.stf.alert_error("dts_pnltsat_info error" + dts_pnltsat_info);
};
scwin.dts_pnlt_history_OnLoadError = function() {
    $c.win.alert("dts_pnlt_history error" + dts_pnlt_history);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_pnlt_history, "벌점부과상세내역 ", "", "8");
};
scwin.btn_Search_onclick = function() {
    fn_Search();
};
scwin.img_impost_dd_onclick = function() {
    popUpCalendar3(edt_impost_dd);
};
scwin.img_rsnoccr_dd_onclick = function() {
    popUpCalendar2(edt_rsnoccr_dd);
};
scwin.btn_Insert_onclick = function() {
    scwin.fn_Insert();
};
scwin.btn_Clear_onclick = function() {
    scwin.fn_Clear();
};
scwin.trs_Pnlt_Input_OnFail = function() {
    $c.win.alert('trs_Pnlt_Input.OnFail() :' + trs_Pnlt_Input.ErrorMsg);
};
scwin.trs_Pnlt_Input_OnSuccess = function() {
    $c.win.alert("처리완료");

    // 화면 RELOAD
    fn_Search();
    // dataset 초기화
    dts_Pnlt_Input.removeAll();
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
