scwin.gform_onload = function() {
    $c.stf.showObj(txb_isurcd, false); // 히든처리!
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();

    // 가우스헤더 셋팅
    dts_Pnlt_Input.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=PNLTDATA_INOUT";
    dts_Pnlt_Input.reset();

    // 가우스헤더 셋팅
    dts_CautnActDtl.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CAUTN_ACT_DTL_INOUT";
    dts_CautnActDtl.reset();
    dts_CautnActDtl_input.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CAUTN_ACT_DTL_INOUT";
    dts_CautnActDtl_input.reset();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_GetParentValue();
};
