        $c.win.alert("대상회사를 변경한 경우 '조회' 후 입력이 가능합니다.");
        return false;
    }
    if (rpt_dd == "") {
        var url = "/dsclmgt/ULDSTF35119.gfm";
        var winTitle = "주의조치 정보 등록화면";
        await $c.frame.CreateFrame("cautn_form", url, winTitle, 250, 150, 510, 390, "window", 0, 0, true);
    } else {
        $c.win.alert('기존 주의조치 현황 삭제 후, 입력이 가능합니다.');
    }
};
scwin.dts_CautnActDtl_OnLoadCompleted = function(rowcount) {
    var cautn_file_name = dts_CautnActDtl.getCellData(1, "ATTACH_FILE_NM");
    if (typeof cautn_file_name == "undefined" || cautn_file_name == "") {
        document.getElementById("txb_cautn_act_rsn").style.setStyle("backgroundcolor", "#FFFFFF");
        document.getElementById("txb_cautn_act_rsn").style.cursor = "text";
    } else {
        document.getElementById("txb_cautn_act_rsn").style.setStyle("backgroundcolor", "#FFFF99");
        document.getElementById("txb_cautn_act_rsn").style.cursor = "pointer";
    }
};
