};
scwin.img_CautnActDtl_delete_onclick = function() {
    var end_dd = txb_end_dd.getValue();
    if (txb_isur_cd.getValue() != scwin.gIsurCd) {
        $c.win.alert("대상회사를 변경한 경우 '조회' 후 입력이 가능합니다.");
        return false;
    }
    if (end_dd != "") {
        scwin.deleteCautnActDtl();
    } else {
        $c.win.alert('삭제할 내용이 없습니다.');
    }
};
scwin.txb_cautn_act_rsn_ondblclick = function() {
    var cautn_file_name = dts_CautnActDtl.getCellData(1, "ATTACH_FILE_NM");
